using Avalonia;
using System.Numerics;
namespace WirePulse;

/// Conservative patch bounds: never cull rear wire that remains visible through the front mesh.
/// A patch contains complete edges. Morph bounds include every endpoint's possible displacement.
public sealed class OrbVisibility {
 public sealed record Patch(int[] Edges,int[] Vertices,Vector3 Center,double Radius);
 readonly OrbMesh mesh;readonly Patch[] patches;readonly bool[] activeVertices,activeEdges;
 public bool All{get;private set;}=true;public int ProjectedVertices{get;private set;}
 public OrbVisibility(OrbMesh mesh){this.mesh=mesh;activeVertices=new bool[mesh.Vertices.Length];activeEdges=new bool[mesh.Edges.Length];var bins=new Dictionary<int,List<int>>();for(int i=0;i<mesh.Edges.Length;i++){var(a,b)=mesh.Edges[i];var p=mesh.Vertices[a];var q=mesh.Vertices[b];double x=(p.X+q.X)*.5,y=(p.Y+q.Y)*.5,z=(p.Z+q.Z)*.5;int lat=Math.Clamp((int)((Math.Acos(Math.Clamp(y,-1,1))/Math.PI)*8),0,7),lon=Math.Clamp((int)((Math.Atan2(z,x)+Math.PI)/(Math.PI*2)*16),0,15),key=lat*16+lon;if(!bins.TryGetValue(key,out var list))bins[key]=list=[];list.Add(i);}patches=bins.Values.Select(edges=>{var vertices=edges.SelectMany(i=>new[]{mesh.Edges[i].A,mesh.Edges[i].B}).Distinct().ToArray();double minX=1,minY=1,minZ=1,maxX=-1,maxY=-1,maxZ=-1;foreach(int i in vertices){var v=mesh.Vertices[i];minX=Math.Min(minX,v.X);maxX=Math.Max(maxX,v.X);minY=Math.Min(minY,v.Y);maxY=Math.Max(maxY,v.Y);minZ=Math.Min(minZ,v.Z);maxZ=Math.Max(maxZ,v.Z);}var center=new Vector3((float)((minX+maxX)*.5),(float)((minY+maxY)*.5),(float)((minZ+maxZ)*.5));double radius=vertices.Max(i=>{var v=mesh.Vertices[i];return Math.Sqrt(Math.Pow(v.X-center.X,2)+Math.Pow(v.Y-center.Y,2)+Math.Pow(v.Z-center.Z,2));});return new Patch(edges.ToArray(),vertices,center,radius+1e-6);}).ToArray();}
 public bool Vertex(int i)=>All||activeVertices[i];public bool Edge(int i)=>All||activeEdges[i];
 public void Prepare(ReadOnlySpan<double> bands,double angle,double radius,double x,double y,double deformation,bool full,Rect? clip){All=clip==null;ProjectedVertices=mesh.Vertices.Length;if(All)return;double maxEnergy=0;foreach(double e in bands)maxEnergy=Math.Max(maxEnergy,e);double maxGrowth=1+deformation*(full?.38:.07)*maxEnergy;var view=clip!.Value;double extent=radius*maxGrowth;if(view.Contains(new Rect(x-extent,y-extent,extent*2,extent*2))){All=true;return;}Array.Clear(activeVertices);Array.Clear(activeEdges);double ca=Math.Cos(angle),sa=Math.Sin(angle),ct=Math.Cos(.23),st=Math.Sin(.23);foreach(var patch in patches){double energy=0;foreach(int i in patch.Vertices){var p=mesh.Vertices[i];energy=Math.Max(energy,p.Envelope*bands[p.Band]);}double growth=1+deformation*(full?.38:.07)*energy,mid=(1+growth)*.5;var c=patch.Center;double px=c.X*ca-c.Z*sa,pz=c.X*sa+c.Z*ca,py=c.Y*ct-pz*st,r=radius*(patch.Radius*growth+c.Length()*(growth-1)*.5)+.01,cx=x+px*radius*mid,cy=y+py*radius*mid;if(!view.Intersects(new Rect(cx-r,cy-r,r*2,r*2)))continue;foreach(int i in patch.Edges)activeEdges[i]=true;foreach(int i in patch.Vertices)activeVertices[i]=true;}ProjectedVertices=activeVertices.Count(x=>x);}
}
